<script setup lang="ts">
/**
 * Menu's command list on right-click or long-press, at the press point (`design/components/context-menu.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/context-menu.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  provide,
  ref,
  useId,
  useTemplateRef,
  watch,
} from 'vue'

import * as zag from '@zag-js/menu'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  agentMember,
  chooseMenuEntry,
  followHighlight,
  menuChoices,
  useDirection,
  useMediaQuery,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/context-menu.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import ContextMenuSubmenu from './ContextMenuSubmenu.vue'
import Kbd from '../structure/Kbd.vue'
import type { MenuEntry } from './Menu.vue'

export interface ContextMenuProps {
  /**
   * Entries in Menu's grammar (`menu.md`), including submenus; this member does not redefine it.
   */
  entries: MenuEntry[]
  /**
   * Menu's `presentation`, passed through (`menu.md`; the sheet presentation): `'auto'` uses a
   * sheet below `30rem`, and `'popover'` keeps the press-point popper at every width. Like
   * Menu's, the union is closed and has no always-`'sheet'` value.
   */
  presentation?: 'auto' | 'popover'
}

defineOptions({ name: 'ContextMenu', inheritAttrs: false })

const props = withDefaults(defineProps<ContextMenuProps>(), { presentation: 'auto' })
const emit = defineEmits<{ openChange: [open: boolean] }>()
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const uid = useId()
const restoreTo = ref(null as HTMLElement | null)
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const surface = useTemplateRef<HTMLElement>('surface')
const phone = useMediaQuery('phone')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const flat = computed(() =>
  props.entries.flatMap((entry) =>
    entry.kind === 'submenu'
      ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
      : [entry],
  ),
)
const remember = computed(() => (pressed: boolean) => {
  const active = document.activeElement
  const focused = active instanceof HTMLElement && active !== document.body ? active : null
  restoreTo.value = pressed ? focused : (focused ?? restoreTo.value)
})
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    positioning: { placement: 'right-start', gutter: 0 },
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
    onSelect: (details) => {
      flat.value.forEach(
        (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
      )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
provide('polymorph:ContextMenu', {
  get api() {
    return api.value
  },
  get service() {
    return service
  },
})
const effect1 = () => {
  followHighlight(panel.value, api.value.highlightedValue)
}
onMounted(effect1)
watch(() => api.value.highlightedValue, effect1, { flush: 'post' })
const effect2 = () => {
  api.value.open ||
    requestAnimationFrame(() => (restoreTo.value?.focus(), (restoreTo.value = null)))
}
watch(() => api.value.open, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'ContextMenu',
    element: () => surface.value,
    state: () => ({ open: api.value.open, entries: menuChoices(props.entries) }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          chooseMenuEntry(props.entries, value) && api.value.open && api.value.setOpen(false),
      },
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <span
    ref="surface"
    v-bind="api.getContextTriggerProps()"
    :class="styles.surface"
    :style="{ userSelect: 'auto', WebkitUserSelect: 'auto' }"
    data-member="context-menu"
    @contextmenu.capture="remember(false)"
    @pointerdown.capture="remember(true)"
  >
    <slot />
  </span>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.content"
        :style="{
          '--radix-context-menu-content-available-height': 'var(--available-height)',
          '--radix-context-menu-content-transform-origin': 'var(--transform-origin)',
        }"
        :hidden="undefined"
        data-member="context-menu"
        @focus="followHighlight(panel, api.highlightedValue)"
      >
        <template v-for="(entry, index) in entries" :key="index">
          <div
            v-if="entry.kind === 'separator'"
            v-bind="api.getSeparatorProps()"
            :class="styles.separator"
          />
          <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
            {{ entry.label }}
          </div>
          <div
            v-else-if="entry.kind === 'checkbox'"
            v-bind="
              api.getOptionItemProps({
                type: 'checkbox',
                value: entry.label,
                checked: entry.checked,
                disabled: entry.disabled,
                closeOnSelect: false,
                onCheckedChange: entry.onCheckedChange,
              })
            "
            :class="[styles.item, styles.checkbox]"
            tabindex="-1"
            @focus="api.setHighlightedValue(entry.label)"
          >
            <span :class="styles.check">
              <Icon v-if="entry.checked" name="confirm" size="sm" />
            </span>
            <span :class="styles.label">
              {{ entry.label }}
            </span>
          </div>
          <ContextMenuSubmenu v-else-if="entry.kind === 'submenu'" :entry="entry" />
          <div
            v-else
            v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
            :class="styles.item"
            :data-tone="entry.tone ?? 'neutral'"
            tabindex="-1"
            @focus="api.setHighlightedValue(entry.label)"
          >
            <span v-if="entry.icon !== undefined" :class="styles.glyph">
              <Icon :name="entry.icon" size="sm" />
            </span>
            <span :class="styles.label">
              {{ entry.label }}
            </span>
            <span v-if="entry.kbd !== undefined" :class="styles.hint">
              <Kbd>
                {{ entry.kbd }}
              </Kbd>
            </span>
          </div>
        </template>
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        :class="sheet.panel"
        data-presentation="sheet"
        :data-state="api.open ? 'open' : 'closed'"
        tabindex="-1"
      >
        <!-- panel -->
        <div
          ref="panel"
          v-bind="api.getContentProps()"
          :class="styles.sheetList"
          :hidden="undefined"
          data-member="context-menu"
          @focus="followHighlight(panel, api.highlightedValue)"
        >
          <template v-for="(entry, index) in flat" :key="index">
            <div
              v-if="entry.kind === 'separator'"
              v-bind="api.getSeparatorProps()"
              :class="styles.separator"
            />
            <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
              {{ entry.label }}
            </div>
            <div
              v-else-if="entry.kind === 'checkbox'"
              v-bind="
                api.getOptionItemProps({
                  type: 'checkbox',
                  value: entry.label,
                  checked: entry.checked,
                  disabled: entry.disabled,
                  closeOnSelect: false,
                  onCheckedChange: entry.onCheckedChange,
                })
              "
              :class="[styles.item, styles.checkbox]"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span :class="styles.check">
                <Icon v-if="entry.checked" name="confirm" size="sm" />
              </span>
              <span :class="styles.label">
                {{ entry.label }}
              </span>
            </div>
            <div
              v-else
              v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
              :class="styles.item"
              :data-tone="entry.tone ?? 'neutral'"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span v-if="entry.icon !== undefined" :class="styles.glyph">
                <Icon :name="entry.icon" size="sm" />
              </span>
              <span :class="styles.label">
                {{ entry.label }}
              </span>
              <span v-if="entry.kbd !== undefined" :class="styles.hint">
                <Kbd>
                  {{ entry.kbd }}
                </Kbd>
              </span>
            </div>
          </template>
        </div>
      </div>
    </div>
  </Teleport>
</template>
